package com.pp.shaderlod.optimization.makeupshadow.mixin;import com.llamalad7.mixinextras.injector.ModifyReturnValue;import com.llamalad7.mixinextras.sugar.Local;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.At;import net.irisshaders.iris.pipeline.programs.ShaderSupplier;import net.irisshaders.iris.pipeline.IrisRenderingPipeline;import net.irisshaders.iris.shaderpack.programs.ProgramSource;import com.pp.shaderlod.optimization.makeupshadow.MakeUpShadowRuntime;@Mixin(targets="net.irisshaders.iris.pipeline.programs.ShaderCreator",remap=false)public abstract class ShadowSupplierMixin{@ModifyReturnValue(method="create",at=@At("RETURN"),require=1)private static ShaderSupplier own(ShaderSupplier s,@Local(argsOnly=true) IrisRenderingPipeline owner,@Local(argsOnly=true) ProgramSource source){if(s==null)return null;if(source==null||source.getParent()==null||source.getName()==null||!source.getName().startsWith("gbuffers_terrain"))return s;return new ShaderSupplier(s.key(),s.id(),()->{var p=s.shader().get();if(p!=null)MakeUpShadowRuntime.own(owner,source.getParent().getPack(),source.getName(),p.getProgramId());return p;});}}
